5	/**
6	 * Prevent the NGG v4 React SPA from intercepting clicks on the Imagify Bulk
7	 * Optimization submenu link.
8	 *
9	 * NGG v4 attaches a bubble-phase click listener to the document that captures
10	 * all <a> clicks and routes them through its client-side router, which doesn't
11	 * know about the Imagify page and falls back to the Galleries tab. A capture-
12	 * phase listener registered before the SPA boots intercepts the click first
13	 * and forces a real browser navigation via window.location.href.
14	 *
15	 * @since 2.2.9
16	 */
17	function _imagify_ngg_fix_spa_bulk_link() {
18		if ( ! class_exists( 'Imagely\NGG\Admin\App' ) ) {
19			return;
20		}
21		$slug = esc_js( imagify_get_ngg_bulk_screen_slug() );
22		?>
23		<script>
24		document.addEventListener( 'click', function( e ) {
25			var a = e.target.closest( 'a[href*="page=<?php echo $slug; ?>"]' );
26			if ( a ) {
27				e.stopImmediatePropagation();
28				e.preventDefault();
29				window.location.href = a.href;
30			}
31		}, true );
32		</script>
33		<?php
34	}
