4	namespace Imagify\Webp\RewriteRules;
5	
6	use Imagify\EventManagement\SubscriberInterface;
7	use Imagify\Notices\Notices;
8	use Imagify\WriteFile\WriteFileInterface;
9	
10	/**
11	 * Display WebP images on the site with rewrite rules.
12	 *
13	 * @since 1.9
14	 */
15	class Display implements SubscriberInterface {
16		/**
17		 * Configuration file writer.
18		 *
19		 * @var WriteFileInterface|null
20		 */
21		protected $server_conf = null;
22	
23		/**
24		 * Option value.
25		 *
26		 * @var string
27		 * @since 1.9
28		 */
29		const OPTION_VALUE = 'rewrite';
30	
31		/**
32		 * Returns an array of events this subscriber listens to
33		 *
34		 * @return array
35		 */
36		public static function get_subscribed_events() {
37			return [
38				'imagify_settings_on_save'   => [ 'maybe_add_rewrite_rules', 10 ],
39				'imagify_settings_webp_info' => 'maybe_add_webp_info',
40				'imagify_activation'         => 'activate',
41				'imagify_deactivation'       => 'deactivate',
42			];
43		}
44	
45		/**
46		 * If display WebP images via rewrite rules, add the rules to the .htaccess/etc file.
47		 *
48		 * @since 1.9
49		 *
50		 * @param array $values The option values.
51		 *
52		 * @return array
53		 */
54		public function maybe_add_rewrite_rules( $values ) {
55			$was_enabled = (bool) get_imagify_option( 'display_nextgen' );
56			$is_enabled  = ! empty( $values['display_nextgen'] );
57	
58			// Which method?
59			$old_value = get_imagify_option( 'display_nextgen_method' );
60			$new_value = ! empty( $values['display_nextgen_method'] ) ? $values['display_nextgen_method'] : '';
61	
62			// Decide when to add or remove rules.
63			$is_rewrite  = self::OPTION_VALUE === $new_value;
64			$was_rewrite = self::OPTION_VALUE === $old_value;
65	
66			if ( ! $this->get_server_conf() ) {
67				return $values;
68			}
69	
70			$result = false;
71	
72			if ( $is_enabled && $is_rewrite && ( ! $was_enabled || ! $was_rewrite ) ) {
73				// Add the rewrite rules.
74				$result = $this->get_server_conf()->add();
75			} elseif ( $was_enabled && $was_rewrite && ( ! $is_enabled || ! $is_rewrite ) ) {
76				// Remove the rewrite rules.
77				$result = $this->get_server_conf()->remove();
78			}
79	
80			if ( ! is_wp_error( $result ) ) {
81				return $values;
82			}
83	
84			// Display an error message.
85			if ( is_multisite() && strpos( wp_get_referer(), network_admin_url( '/' ) ) === 0 ) {
86				Notices::get_instance()->add_network_temporary_notice( $result->get_error_message() );
87	
88				return $values;
89			}
90	
91			Notices::get_instance()->add_site_temporary_notice( $result->get_error_message() );
92	
93			return $values;
94		}
95	
96		/**
97		 * If the conf file is not writable, add a warning.
98		 *
99		 * @since 1.9
100		 */
101		public function maybe_add_webp_info() {
102			global $is_nginx;
103	
104			if ( 'avif' === get_imagify_option( 'optimization_format' ) ) {
105				return;
106			}
107	
108			$conf = $this->get_server_conf();
109	
110			if ( ! $conf ) {
111				return;
112			}
113	
114			$writable = $conf->is_file_writable();
115	
116			if ( is_wp_error( $writable ) ) {
117				$rules = $conf->get_new_contents();
118	
119				if ( ! $rules ) {
120					// Uh?
121					return;
122				}
123	
124				printf(
125					/* translators: %s is a file name. */
126					esc_html__( 'If you choose to use rewrite rules, you will have to add the following lines manually to the %s file:', 'imagify' ),
127					'<code>' . $this->get_file_path( true ) . '</code>' // phpcs:ignore WordPress.Security.EscapeOutput.OutputNotEscaped
128				);
129	
130				echo '<pre class="code">' . esc_html( $rules ) . '</pre>';
131			} elseif ( $is_nginx ) {
132				printf(
133					/* translators: %s is a file name. */
134					esc_html__( 'If you choose to use rewrite rules, the file %s will be created and must be included into the server’s configuration file (then restart the server).', 'imagify' ),
135					'<code>' . $this->get_file_path( true ) . '</code>' // phpcs:ignore WordPress.Security.EscapeOutput.OutputNotEscaped
136				);
137			}
138		}
139	
140		/**
141		 * Add rules on plugin activation.
142		 *
143		 * @since 1.9
144		 */
145		public function activate() {
146			$conf = $this->get_server_conf();
147	
148			if ( ! $conf ) {
149				return;
150			}
151	
152			if ( ! get_imagify_option( 'display_nextgen' ) ) {
153				return;
154			}
155			if ( self::OPTION_VALUE !== get_imagify_option( 'display_nextgen_method' ) ) {
156				return;
157			}
158			if ( is_wp_error( $conf->is_file_writable() ) ) {
159				return;
160			}
161	
162			$conf->add();
163		}
164	
165		/**
166		 * Remove rules on plugin deactivation.
167		 *
168		 * @since 1.9
169		 */
170		public function deactivate() {
171			$conf = $this->get_server_conf();
172	
173			if ( ! $conf ) {
174				return;
175			}
176			if ( ! get_imagify_option( 'display_nextgen' ) ) {
177				return;
178			}
179			if ( self::OPTION_VALUE !== get_imagify_option( 'display_nextgen_method' ) ) {
180				return;
181			}
182	
183			$file_path  = $conf->get_file_path();
184			$filesystem = \Imagify_Filesystem::get_instance();
185	
186			if ( ! $filesystem->exists( $file_path ) ) {
187				return;
188			}
189			if ( ! $filesystem->is_writable( $file_path ) ) {
190				return;
191			}
192	
193			$conf->remove();
194		}
195	
196		/**
197		 * Get the path to the directory conf file.
198		 *
199		 * @since 1.9
200		 *
201		 * @param  bool $relative True to get a path relative to the site’s root.
202		 *
203		 * @return string|bool The file path. False on failure.
204		 */
205		public function get_file_path( $relative = false ) {
206			if ( ! $this->get_server_conf() ) {
207				return false;
208			}
209	
210			$file_path = $this->get_server_conf()->get_file_path();
211	
212			if ( $relative ) {
213				return \Imagify_Filesystem::get_instance()->make_path_relative( $file_path );
214			}
215	
216			return $file_path;
217		}
218	
219		/**
220		 * Get the server conf instance.
221		 *
222		 * @since 1.9
223		 *
224		 * @return WriteFileInterface
225		 */
226		protected function get_server_conf() {
227			global $is_apache, $is_iis7, $is_nginx;
228	
229			if ( isset( $this->server_conf ) ) {
230				return $this->server_conf;
231			}
232	
233			if ( $is_apache ) {
234				$this->server_conf = new Apache();
235			} elseif ( $is_iis7 ) {
236				$this->server_conf = new IIS();
237			} elseif ( $is_nginx ) {
238				$this->server_conf = new Nginx();
239			}
240	
241			return $this->server_conf;
242		}
243	}
