// Create a tiny JPEG using raw JFIF bytes — a 1x1 white pixel JPEG
// that is already at minimum quality, making WebP larger due to format overhead
const fs = require('fs');

// Minimal valid 1x1 red JPEG (pre-built bytes)
// We'll create a small noisy PNG using canvas if available, otherwise use a pre-encoded tiny JPEG
try {
  const { createCanvas } = require('canvas');
  const canvas = createCanvas(16, 16);
  const ctx = canvas.getContext('2d');
  // Fill with random noise - hard for WebP to beat
  const img = ctx.createImageData(16, 16);
  for (let i = 0; i < img.data.length; i++) img.data[i] = Math.floor(Math.random() * 256);
  ctx.putImageData(img, 0, 0);
  fs.writeFileSync('/tmp/noisy-test.png', canvas.toBuffer('image/png'));
  console.log('canvas: created noisy PNG');
} catch(e) {
  console.log('no canvas: ' + e.message);
}
